import{_ as u,a0 as r,w as p,s as m,ao as i,I as l,x as e,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"戴文的Linux内核专题：28 编译与安装 | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux内核专题：28 编译与安装 | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux内核专题：28 编译与安装 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux内核专题：28 编译与安装 | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/28 The Linux Kernel--Compiling and Installing","title":"戴文的Linux内核专题：28 编译与安装","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/28 The Linux Kernel--Compiling and Installing.md","filePath":"[post].md"}'),s={name:"The Linux Kernel/28 The Linux Kernel--Compiling and Installing.md"};function d(g,t,x,q,T,C){const o=r("Link");return p(),m("div",null,[t[14]||(t[14]=i('<h1 id="戴文的linux内核专题-28-编译与安装" tabindex="-1">戴文的Linux内核专题：28 编译与安装 <a class="header-anchor" href="#戴文的linux内核专题-28-编译与安装" aria-label="Permalink to “戴文的Linux内核专题：28 编译与安装”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.762/.jpg" alt=""></p><p>你好！在花费了大量的时间在配置你需要的内核后，你现在可以编译它了。源代码是纯文本形式的C代码。这对人来可读但是对机器可不是这样。编译会将代码转换成计算机可理解的一种称之为二进制码的形式(1是 [开]，0 是 [关])。编译同样会将所有内核代码文件变成一个内核的文件。</p><p>为了编译内核，在内核源代码相同目录下，在终端内输入&quot;make&quot;。这会花费一些时间。完成之后，必须通过&quot;make modules&quot;来编译模块。为了从一开始就简化编译过程，输入&quot;make; make modules&quot;。这会先编译接着是模块，而不用用户再回来输入&quot;make modules&quot;。</p><p><img src="http://www.linux.org/attachments/compiling_01-png.763/.jpg" alt=""></p><p>警告：在你安装一个内核时，备份所有的重要数据，确保有一份/boot目录备份在FAT32的存储卡上。这可以在如果安装失败后帮助修复系统。FAT32不会存储权限，因此它更容易被用作live盘来还原数据。记住设置原始文件权限和可执行位。</p><p>一旦编译已经成功完成，我们可以安装内核到本地系统中(我会马上解释如何在其他系统上安装内核[交叉编译])。在相同的终端下，在编译完成后，输入&quot;make install&quot;。这会在/boot目录下存放一些文件。&quot;vmlinuz&quot;(或者其他相似的名字)是内核自身。&quot;initrd&quot;是基于内存的文件系统，它被置于内存中且在启动中使用。&quot;System-map&quot;包含了一张内核符号列表。这些全局变量和函数用于内核代码。&quot;config&quot; 是内核的配置文件。grub.cfg会自动更新。然而，有些bootloder需要手动配置。内核安装器会自动配置Grub，LILO和SysLinux bootloder。像BURG这类bootloder需要手动配置。模块的安装同样需要输入&quot;make modules install&quot;。</p><p><img src="http://www.linux.org/attachments/compiling_04-png.764/.jpg" alt=""></p><p>注：内核和模块的安装可以写在一行-“make install &amp;&amp; make modules_install”。</p><p><img src="http://www.linux.org/attachments/compiling_05-png.765/.jpg" alt=""></p><p>一旦上面的过程完成了，用户可以通过重启系统并在开机后在终端内输入&quot;uname -r&quot;来确保内核已经安装。如果系统无法启动或者uname报告你预期外的版本号，这个问题可能众多问题之一引起。或者是bootloader没有正确设置，特性/配置冲突，编译失败，不正确的安装，或者其他原因。找出问题源头最好的方法是查看系统日志(如果系统已经启动到足以产生日志)。&quot;dmsg&quot;是一个在屏幕上打印内核日志的命令。查看错误、警告或者未预料的结果。如果系统没有启动或者没有足够启动完全来生成日志，使用live linux盘来执行诊断和修复。如果所有的都失败了，再次编译内核并确保你已经用root或者&quot;sudo&quot;安装了内核。</p><p>注：最好的修复系统的方式是使用live Linux发行版来移除新的/损坏的内核，接着手动修复Grub文件(或者复制一个备份)。</p><p>一些Linux用户也喜欢安装内核文档，但这并不是必要。对于那些想要安装文档的用户，输入这行，这里的version是你的内核版本号 &quot;install -d /usr/share/doc/linux-VERSION &amp;&amp; cp -r Documentation/* /usr/share/doc/linux-VERSION&quot;(VERSION 是内核版本号)。很明显，这需要root特权。</p><p>要是想编译一个如你目前内核一样特性的内核，输入这条命令&quot;zcat /proc/config.gz &gt; .config&quot;。这个文件可能不存在，如果是这样，你可能需要询问你发行版/内核的开发者这个文件。&quot;zcat&quot;命令解压并写入数据到一个&quot;.config&quot;文件中。记住把&quot;.config&quot;放到合适的位置。这个文件应该放置在Linux内核目录下，并允许它替换当前的文件。接着，像往常一样编译安装你的内核即可。</p><p>交叉编译稍微有点不同。为目标系统配置内核。确保内核配置完后，它是以交叉编译配置的。当交叉编译时，需要熟悉两条术语。&quot;Host&quot;是执行编译的系统，&quot;Target&quot;是接收新内核的系统。确保Host主机系统有合适的编译器。比如，对于ARM系统的交叉编译，用户需要在主机系统上有gcc-arm-linux-gnueabi。通常来说，开发者可以在他们的包管理器上搜寻或者Google到合适/最好的适合他们需要的交叉编译器。比如用于ARM系统交叉编译的命令是&quot;make ARCH=arm CROSS_COMPILE=arm-linux-gnueabi-&quot;。&quot;ARCH=arm&quot;指的是目标处理器的类型，&quot;CROSS_COMPILE&quot;指明了交叉编译器。注意交叉编译器前面缺少了&quot;gcc-&quot;并以连字符结束。这是用户在使用交叉编译器作为参数使用时必须使用的格式。模块可以通过输入&quot;make ARCH=arm CROSS_COMPILE=arm-linux-gnueabi- modules&quot;来交叉编译。为了在目标系统上安装内核，将内核文件夹复制到目标系统上。一旦文件已在目标系统上并在该目录下打开了终端，输入&quot;make install &amp;&amp; make modules_install&quot;。当然你必须是root或者使用&quot;sudo&quot;。</p>',15)),l("p",null,[t[1]||(t[1]=e("信息：Kernel.org放了一个支持的交叉编译器列表(",-1)),a(o,{href:"https://www.kernel.org/pub/tools/crosstool/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.kernel.org/pub/tools/crosstool/",-1)])]),_:1}),t[2]||(t[2]=e(")。",-1))]),t[15]||(t[15]=i(`<h3 id="安装编译总结" tabindex="-1">安装编译总结: <a class="header-anchor" href="#安装编译总结" aria-label="Permalink to “安装编译总结:”">​</a></h3><h4 id="标准" tabindex="-1">标准: <a class="header-anchor" href="#标准" aria-label="Permalink to “标准:”">​</a></h4><pre><code>make &amp;&amp; make modules &amp;&amp; make install &amp;&amp; make modules_install
</code></pre><h4 id="做一个更新的版本或者重整你的内核" tabindex="-1">做一个更新的版本或者重整你的内核: <a class="header-anchor" href="#做一个更新的版本或者重整你的内核" aria-label="Permalink to “做一个更新的版本或者重整你的内核:”">​</a></h4><pre><code>zcat /proc/config.gz &gt; .config &amp;&amp;  make &amp;&amp; make modules &amp;&amp; make install &amp;&amp; make modules_install
</code></pre><h4 id="交叉编译" tabindex="-1">交叉编译: <a class="header-anchor" href="#交叉编译" aria-label="Permalink to “交叉编译:”">​</a></h4><pre><code>make ARCH={TARGET-ARCHITERCTURE} CROSS_COMPILE={COMPILER}; make ARCH={TARGET-ARCHITERCTURE} CROSS_COMPILE={COMPILER} modules &amp;&amp; make install &amp;&amp; make modules_install
</code></pre><p>下篇文章中，我们会讨论加入和激活模块。谢谢！</p><hr>`,9)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),a(o,{href:"http://www.linux.org/threads/the-linux-kernel-compiling-and-installing.5208/"},{default:n(()=>[...t[3]||(t[3]=[e("http://www.linux.org/threads/the-linux-kernel-compiling-and-installing.5208/",-1)])]),_:1})]),l("p",null,[t[7]||(t[7]=e("译者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[8]||(t[8]=e(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[11]||(t[11]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原创翻译，",-1)),a(o,{href:"http://linux.cn/"},{default:n(()=>[...t[10]||(t[10]=[e("Linux中国",-1)])]),_:1}),t[13]||(t[13]=e(" 荣誉推出",-1))])])}const f=u(s,[["render",d]]);export{L as __pageData,f as default};
